const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const asId = (v) => (typeof v === 'string' && UUID_RE.test(v.trim()) ? v.trim().toLowerCase() : null);
const stop = (status, message, extra) => [{ json: { allowed: false, result: { status, ...(extra || {}), message } } }];
const invalid = (field, message) => stop('invalid_input', message, { field });
const SERVER_FIELD = ' (lỗi cấu hình workflow, không phải do admin). Dừng và báo admin kiểm tra n8n.';
const asVersion = (v) => {
  const n = typeof v === 'string' && /^\d+$/.test(v.trim()) ? Number(v.trim()) : v;
  return Number.isInteger(n) && n >= 1 ? n : null;
};
const req = $input.first().json;
const threadId = asId(req.thread_id);
if (!threadId) return invalid('thread_id', 'thread_id không hợp lệ' + SERVER_FIELD);
const adminId = asId(req.admin_user_id);
if (!adminId) return invalid('admin_user_id', 'admin_user_id không hợp lệ' + SERVER_FIELD);
const campaignId = asId(req.campaign_id);
if (!campaignId) return invalid('campaign_id', 'campaign_id không hợp lệ. Lấy id từ kết quả find_announcement_events, không tự đặt; chưa chắc thì hỏi admin.');

const SUBJECT_MAX = 150;
const BODY_MAX = 5000;
const RAW_LIMIT = { subject: 1000, body: 20000 };
const CONTROL_RE = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F-\u009F\u{200B}-\u{200F}\u{202A}-\u{202E}\u{2060}-\u{2064}\u{2066}-\u{2069}\u{FEFF}]/gu;
const countChars = (s) => Array.from(s).length;

// Tước mọi thẻ HTML, lặp đến khi ổn định để thẻ lồng như <<b>script> không còn sót.
// Chữ như "a < b and c > d" không phải thẻ (sau "<" phải là chữ cái, "/", "!" hoặc "?") nên giữ nguyên.
const stripHtml = (input) => {
  let s = input;
  for (let i = 0; i < 50; i += 1) {
    const before = s;
    s = s.replace(/<!--[\s\S]*?-->/g, '')
      .replace(/<(script|style)\b[^<>]*>[\s\S]*?<\/\1\s*>/gi, '')
      .replace(/<br\s*\/?>|<\/(?:p|div|li|tr|h[1-6])\s*>/gi, '\n')
      .replace(/<\/?[a-zA-Z!?][^<>]*>/g, '');
    if (s === before) break;
  }
  return s.replace(/<(?=\/?[a-zA-Z!?])/g, '');
};

const clean = (value, field) => {
  if (typeof value !== 'string') return { empty: true };
  if (value.length > RAW_LIMIT[field]) return { tooLong: true };
  let s = value.normalize('NFC').replace(/\r\n|[\r\u{2028}\u{2029}\u0085]/gu, '\n').replace(CONTROL_RE, '');
  const stripped = stripHtml(s);
  const htmlRemoved = stripped !== s;
  s = stripped;
  if (field === 'subject') {
    s = s.replace(/\s+/g, ' ').trim();
  } else {
    s = s.replace(/[ \t]+\n/g, '\n').replace(/(?<=\S)[ \t]{2,}(?=\S)/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
  }
  return { text: s, htmlRemoved, empty: s.length === 0 };
};

const subject = clean(req.subject, 'subject');
const body = clean(req.body, 'body');
const labels = { subject: 'tiêu đề', body: 'nội dung' };
const checks = [['subject', subject, SUBJECT_MAX], ['body', body, BODY_MAX]];
for (const [field, c, max] of checks) {
  if (c.tooLong || (c.text && countChars(c.text) > max)) {
    return stop('invalid_input', 'Phần ' + labels[field] + ' quá dài (tối đa ' + max + ' ký tự). Viết ngắn lại rồi lưu lại, không cắt cụt.', { field, reason: 'too_long', max });
  }
}
for (const [field, c] of checks) {
  if (c.empty) return stop('needs_content', 'Phần ' + labels[field] + ' đang trống (hoặc chỉ gồm thẻ HTML/ký tự điều khiển). Hãy viết văn bản thuần tiếng Việt rồi lưu lại.', { field });
}
const notes = subject.htmlRemoved || body.htmlRemoved ? ['html_stripped'] : [];
return [{ json: { allowed: true, notes, request: { p_thread_id: threadId, p_admin_id: adminId, p_campaign_id: campaignId, p_subject: subject.text, p_body: body.text } } }];

const MIGRATION_MESSAGE = 'Chức năng thông báo chưa sẵn sàng (cơ sở dữ liệu chưa cập nhật). Báo admin chạy migration.';
const GENERIC_MESSAGE = 'Chức năng thông báo tạm thời không dùng được (lỗi kết nối hoặc cơ sở dữ liệu Supabase). Dừng và báo admin kiểm tra Supabase và tab Executions của n8n.';
const unavailable = (message) => [{ json: { status: 'service_unavailable', message } }];
const res = $input.first().json || {};
const http = Number(res.statusCode);
const body = res.body;
if (res.error || !Number.isFinite(http)) return unavailable(GENERIC_MESSAGE);
if (http < 200 || http >= 300) {
  const code = body && typeof body === 'object' ? String(body.code || '') : '';
  return unavailable(http === 404 || code === 'PGRST202' ? MIGRATION_MESSAGE : GENERIC_MESSAGE);
}
if (!body || typeof body !== 'object' || Array.isArray(body) || typeof body.status !== 'string') return unavailable(GENERIC_MESSAGE);
// RPC không bao giờ trả email; vẫn loại các khóa có thể chứa địa chỉ để model không bao giờ thấy.
const scrub = (value) => {
  if (Array.isArray(value)) return value.map(scrub);
  if (value && typeof value === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(value)) {
      if (/e-?mail/i.test(k) || /^recipients$/i.test(k)) continue;
      out[k] = scrub(v);
    }
    return out;
  }
  return value;
};
const b = scrub(body);
const num = (v, fallback) => (Number.isFinite(Number(v)) ? Number(v) : fallback);
const GENERIC = {
  forbidden: 'Admin hiện tại không có quyền với thông báo này hoặc cuộc trò chuyện không thuộc admin này. Dừng và báo admin.',
  not_found: 'Không tìm thấy thông báo này trong cuộc trò chuyện hiện tại. Kiểm tra lại id hoặc dùng get_announcement_status để xem thông báo mới nhất.',
  invalid_input: 'Dữ liệu gửi lên không hợp lệ. Sửa lại theo mô tả tool rồi thử lại, hoặc hỏi admin nếu thiếu thông tin.',
};
const describe = (r) => {
  if (r.status === 'ok') {
    const a = r.announcement || {};
    const version = num(a.version, 1);
    const count = num(a.registrant_count, 0);
    if (r.unchanged) return 'Bản nháp không thay đổi so với version ' + version + ' đã lưu (nội dung giống hệt), không tạo version mới. Trình bày lại nguyên văn nếu admin cần.';
    const head = !r.created && version > 1 ? 'Đã lưu version ' + version + ' mới của bản nháp (thư thử cũ, nếu có, mất hiệu lực). ' : 'Đã lưu bản nháp (version ' + version + '). ';
    return head + 'Hãy trình bày NGUYÊN VĂN tiêu đề và nội dung cho admin cùng số người sẽ nhận (' + count + '), mời admin đọc rồi dừng chờ phản hồi. Chưa gửi cho ai, không gọi approve_and_send_announcement trong lượt này.';
  }
  if (r.status === 'campaign_not_found') return 'Không tìm thấy sự kiện này. Dùng find_announcement_events để tìm lại hoặc hỏi admin.';
  if (r.status === 'version_limit') return 'Bản nháp đã đạt giới hạn 50 version nên không sửa thêm được. Báo admin; cần thì tạo thông báo mới cho sự kiện.';
  if (r.status === 'invalid_input') {
    const field = r.field === 'subject' ? 'tiêu đề' : r.field === 'body' ? 'nội dung' : String(r.field || 'dữ liệu');
    return 'Phần ' + field + ' không hợp lệ (' + (r.reason || 'không rõ lý do') + (r.max ? ', tối đa ' + r.max + ' ký tự' : '') + '). Sửa lại rồi lưu lại.';
  }
  return null;
};
const found = describe(b);
const info = typeof found === 'string' ? { message: found } : found;
const { message, ...extra } = info || {};
return [{ json: { ...b, ...extra, message: message || GENERIC[b.status] || ('Trạng thái "' + b.status + '" chưa được nhận diện. Dừng và báo admin kết quả này.') } }];
